using System.IO;
using System.Text.Json;
using VisionPlugins.Calibration;
static class Program {
 [STAThread] static int Main(string[] args){try{Run(args);return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 static void Run(string[] args){
using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-calibration-evidence.json"));
foreach(var row in evidence.RootElement.GetProperty("fixtureRuntime").EnumerateArray().Where(r=>r.TryGetProperty("count",out _)&&r.TryGetProperty("code",out var code)&&code.GetUInt32()==0)){
 int count=row.GetProperty("count").GetInt32();if(count!=9)continue;
 var frames=Enumerable.Range(0,count).Select(i=>new NImageSolveFrame(new(row.GetProperty("board").GetInt32()==9?1000:10,row.GetProperty("corners").EnumerateArray().Select(c=>new NImageBoardPoint(c.GetProperty("world")[0].GetInt32(),c.GetProperty("world")[1].GetInt32(),c.GetProperty("pixels")[i][0].GetDouble(),c.GetProperty("pixels")[i][1].GetDouble())).ToArray(),[]),new(i%3,i/3,0))).ToArray();
 var result=NImageSolveTranslation.Solve(frames);Console.WriteLine(JsonSerializer.Serialize(new{board=row.GetProperty("board").GetInt32(),original=row.GetProperty("matrix").Clone(),result}));
}

int checks=0;void Check(bool pass,string text){checks++;if(!pass)throw new Exception(text);}var reports=new List<object>();
NImageSolveFrame[] Frames(JsonElement row,int start,int count)=>Enumerable.Range(start,count).Select(i=>new NImageSolveFrame(new(10,row.GetProperty("corners").EnumerateArray().Select(c=>new NImageBoardPoint(c.GetProperty("world")[0].GetInt32(),c.GetProperty("world")[1].GetInt32(),c.GetProperty("pixels")[i][0].GetDouble(),c.GetProperty("pixels")[i][1].GetDouble())).ToArray(),[]),new(i<9?i%3:0,i<9?i/3:0,i<9?0:(i-9)*10))).ToArray();
using(var generated=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-calibration-generated-evidence.json"))){foreach(var source in generated.RootElement.GetProperty("records").EnumerateArray().Select(r=>r.GetProperty("native")).Append(generated.RootElement.GetProperty("rotated").GetProperty("native")).Append(generated.RootElement.GetProperty("perspective").GetProperty("native"))){var result=NImageSolveTranslation.Solve(Frames(source,0,9));Check(result.ErrorCode==0,"Official generated-board translation solve");double difference=source.GetProperty("matrix").EnumerateArray().Select((v,i)=>Math.Abs(v.GetDouble()-result.Matrix[i])).Max();reports.Add(new{kind="translation",board=source.GetProperty("board").GetInt32(),difference,result});Check(difference<1e-3,"Generated-board matrix maximum difference "+difference);}}
using(var rotations=JsonDocument.Parse(File.ReadAllText("docs/plugins/n-image-solver-evidence.json"))){foreach(var source in rotations.RootElement.GetProperty("cases").EnumerateArray()){int count=source.GetProperty("count").GetInt32();var result=NImageSolveRotation.Solve(Frames(source,9,count-9));Check(result.ErrorCode==0,"SDK rotation corner fit");double centerDifference=Math.Max(Math.Abs(result.CenterX-source.GetProperty("center")[0].GetDouble()),Math.Abs(result.CenterY-source.GetProperty("center")[1].GetDouble()));double errorDifference=Math.Abs(result.AverageRadialError-source.GetProperty("rotError").GetDouble());reports.Add(new{kind="rotation",count,centerDifference,errorDifference,result,limitation=count>11?"SDK exports all-frame intersection; original fit uses complete adjacent-frame matches":"All native fitting points available"});if(count==11){Check(centerDifference<1e-4,"Two-rotation original center "+centerDifference);Check(errorDifference<1e-5,"Two-rotation original radial error "+errorDifference);Check(result.Direction==source.GetProperty("direction").GetInt32(),"Original rotation direction");}}}
File.WriteAllText("docs/plugins/n-image-solver-verification.json",JsonSerializer.Serialize(new{scope="Independent numerical stages, coded-corner fixture input isolates detection; not full module parity",checks,reports},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"NImageSolver.Checks: {checks} checks passed; remaining common-corner observations recorded separately");
if(args.Contains("--export-fixture")){
 var decoder=System.Windows.Media.Imaging.BitmapDecoder.Create(new Uri(Path.GetFullPath("tests/NImageCalibration.PluginChecks/Fixtures/hik-i-help-derived.png")),System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat,System.Windows.Media.Imaging.BitmapCacheOption.OnLoad);var bitmap=new System.Windows.Media.Imaging.FormatConvertedBitmap(decoder.Frames[0],System.Windows.Media.PixelFormats.Gray8,null,0);int size=bitmap.PixelWidth;var pixels=new byte[size*size];bitmap.CopyPixels(pixels,size,0);string directory="analysis/full-audit/n-image-calibration/solver-fixture";Directory.CreateDirectory(directory);
 for(int frame=0;frame<14;frame++){var data=new byte[pixels.Length];Array.Fill(data,(byte)255);double angle=frame<9?0:(frame-9)*10*Math.PI/180,cos=Math.Cos(angle),sin=Math.Sin(angle),dx=frame<9?frame%3*10:0,dy=frame<9?frame/3*10:0;for(int y=0;y<size;y++)for(int x=0;x<size;x++){double xx=x-size/2d-dx,yy=y-size/2d-dy,sx=cos*xx+sin*yy+size/2d,sy=-sin*xx+cos*yy+size/2d;int ix=(int)Math.Floor(sx),iy=(int)Math.Floor(sy);if(ix<0||iy<0||ix+1>=size||iy+1>=size)continue;double fx=sx-ix,fy=sy-iy;data[y*size+x]=(byte)((pixels[iy*size+ix]*(1-fx)+pixels[iy*size+ix+1]*fx)*(1-fy)+(pixels[(iy+1)*size+ix]*(1-fx)+pixels[(iy+1)*size+ix+1]*fx)*fy);}
 var image=System.Windows.Media.Imaging.BitmapSource.Create(size,size,96,96,System.Windows.Media.PixelFormats.Gray8,System.Windows.Media.Imaging.BitmapPalettes.Gray256,data,size);var encoder=new System.Windows.Media.Imaging.BmpBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using var output=File.Create(Path.Combine(directory,"frame-"+(frame<9?frame.ToString():"r"+(frame-9))+".bmp"));encoder.Save(output);}
 Console.WriteLine("Exported 9 translations and 5 synthetic rotations around image center; no devices");
}

 }
}

